def main() -> None:
    raw = lzma.decompress(base64.b85decode(DATA.encode("ascii")))
    files = json.loads(raw.decode("utf-8"))
    root = Path.cwd().resolve()
    for relative, content in files.items():
        target = (root / relative).resolve()
        target.relative_to(root)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
    for relative in (
        "tools/apply_production_patch_bundle.py",
        ".github/workflows/apply-production-patch.yml",
    ):
        path = root / relative
        if path.exists():
            path.unlink()
    subprocess.run(["git", "config", "user.name", "github-actions[bot]"], check=True)
    subprocess.run(["git", "config", "user.email", "41898282+github-actions[bot]@users.noreply.github.com"], check=True)
    subprocess.run(["git", "add", "-A"], check=True)
    subprocess.run(["git", "commit", "-m", "Apply complete production stack, MCP, skills and training patch"], check=True)
    subprocess.run(["git", "push", "origin", f"HEAD:{BRANCH}"], check=True)


if __name__ == "__main__":
    main()
